starter_code:
reverseString: function [string][
    panic "Please implement the reverseString function"
]

example_solution:
reverseString: function [string][
    if empty? string -> return ""

    fold.seed:"" string [acc chr] [
        chr ++ acc
    ]
]

test_code:
import.version:3.0.0 {unitt}! 
import {src/reverse-string}!

describe "Reverse String" [
    it "an empty string" [
        expects.be:'equal? @[
            ""
            reverseString ""
        ]
    ]

    it.skip "a word" [
        expects.be:'equal? @[
            "tobor"
            reverseString "robot"
        ]
    ]

    it.skip "a capitalized word" [
        expects.be:'equal? @[
            "nemaR"
            reverseString "Ramen"
        ]
    ]

    it.skip "a sentence with punctuation" [
        expects.be:'equal? @[
            "!yrgnuh m'I"
            reverseString "I'm hungry!"
        ]
    ]

    it.skip "a palindrome" [
        expects.be:'equal? @[
            "racecar"
            reverseString "racecar"
        ]
    ]

    it.skip "an even-sized word" [
        expects.be:'equal? @[
            "reward"
            reverseString "drawer"
        ]
    ]
]
